<div class="page-shell"><header class="page-hero wrap"><span class="eyebrow">Nagpur Citizen Forum</span><h1><?=e($title)?></h1><p><?=e($description)?></p></header><div class="wrap content-grid"><?php if(!$items):?><div class="empty-state">No published records are available yet.</div><?php endif;?><?php foreach($items as $item):?><?php $image=$item[$type==='campaign'?'image_path':'featured_image']??null;$href=$type==='event'?'events/'.$item['slug']:($type==='campaign'?'campaigns/'.$item['slug']:'articles/'.$item['slug']);?><article class="content-card"><?php if($image):?><a class="content-card-image" href="<?=e(url($href))?>"><img src="<?=e(url($image))?>" alt="<?=e($item['title'])?>"></a><?php endif;?><span class="eyebrow"><?=e($item['category']??ucfirst($type))?></span><h2><?=e($item['title'])?></h2><p><?=e(mb_strimwidth($item['summary']??$item['description']??'',0,220,'…'))?></p><?php if($type==='event'&&$item['starts_at']):?><p><strong><?=e(date('j M Y, g:i a',strtotime($item['starts_at'])))?></strong></p><?php endif;?><a class="text-link" href="<?=e(url($href))?>"><?=e($type==='article'?'Read publication':ucfirst($type).' details')?> ↗</a></article><?php endforeach;?></div></div>
